CREATE TABLE IF NOT EXISTS scheduled_tasks (id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT NOT NULL,task_type TEXT NOT NULL CHECK(task_type IN ('webhook_queue','notification_queue','service_expiry','audit_cleanup')),interval_minutes INTEGER NOT NULL CHECK(interval_minutes BETWEEN 1 AND 525600),config TEXT NOT NULL DEFAULT '{}',is_active INTEGER NOT NULL DEFAULT 1,max_attempts INTEGER NOT NULL DEFAULT 3,next_run_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,last_run_at TEXT,last_status TEXT,locked_at TEXT,lock_token TEXT,created_by INTEGER REFERENCES users(id) ON DELETE SET NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS idx_scheduled_tasks_due ON scheduled_tasks(is_active,next_run_at);
CREATE TABLE IF NOT EXISTS scheduled_task_runs (id INTEGER PRIMARY KEY AUTOINCREMENT,task_id INTEGER NOT NULL REFERENCES scheduled_tasks(id) ON DELETE CASCADE,run_token TEXT NOT NULL UNIQUE,status TEXT NOT NULL CHECK(status IN ('running','succeeded','failed','skipped')),attempt INTEGER NOT NULL DEFAULT 1,message TEXT,started_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,finished_at TEXT,duration_ms INTEGER,FOREIGN KEY(task_id) REFERENCES scheduled_tasks(id) ON DELETE CASCADE);
CREATE INDEX IF NOT EXISTS idx_task_runs_task ON scheduled_task_runs(task_id,started_at DESC);
INSERT OR IGNORE INTO schema_migrations(version) VALUES('1.3.0');
